const input = $input.first().json;
const body = input.body;
const headers = input.headers;

const commits = body.commits ?? [];

return [
  {
    json: {
      event: {
        id: headers["x-github-delivery"],
        type: headers["x-github-event"],
        received_at: new Date().toISOString()
      },

      installation: {
        github_installation_id: body.installation?.id ?? null
      },

      repository: {
        github_id: body.repository.id,
        name: body.repository.name,
        full_name: body.repository.full_name,
        owner: body.repository.owner.login,
        private: body.repository.private,
        default_branch: body.repository.default_branch,
        url: body.repository.html_url
      },

      actor: {
        github_id: body.sender?.id ?? null,
        username: body.sender?.login ?? null,
        name: body.pusher?.name ?? null,
        email: body.pusher?.email ?? null
      },

      push: {
        ref: body.ref,
        branch: body.ref?.replace("refs/heads/", ""),
        before: body.before,
        after: body.after,
        forced: body.forced,
        created: body.created,
        deleted: body.deleted
      },

      commits: commits.map(commit => ({
        sha: commit.id,
        message: commit.message,
        timestamp: commit.timestamp,

        author: {
          name: commit.author?.name ?? null,
          email: commit.author?.email ?? null,
          username: commit.author?.username ?? null
        },

        committer: {
          name: commit.committer?.name ?? null,
          email: commit.committer?.email ?? null,
          username: commit.committer?.username ?? null
        },

        added: commit.added ?? [],
        modified: commit.modified ?? [],
        removed: commit.removed ?? []
      })),

      // Filled later by the GitHub Compare API
      changes: []
    }
  }
];

const compare = $input.first().json;

const original = $('Code in JavaScript').first().json;

return [
  {
    json: {
      event: original.event,

      installation: original.installation,

      repository: original.repository,

      actor: original.actor,

      push: original.push,

      commits: original.commits,

      changes: (compare.files ?? []).map(file => ({
        path: file.filename,
        status: file.status,
        additions: file.additions,
        deletions: file.deletions,
        changes: file.changes,
        sha: file.sha,
        patch: file.patch ?? null
      }))
    }
  }
];

